// GetMYWSTEPRenewRetryInterval reads ./Device/Vendor/MSFT/CertificateStore/MY/WSTEP/Renew/RetryInterval.
// Optional. This parameter specifies retry interval when previous renew failed (in days). It
// applies to both manual cert renewal and ROBO cert renewal. Retry schedule will stop at cert
// expiration date. For ROBO renewal failure, the client retries the renewal periodically until the
// device reaches the certificate expiration date. This parameter specifies the waiting period for
// ROBO renewal retries. For manual retry failure, there are no built-in retries. The user can
// retry later. At the next scheduled certificate renewal retry period, the device prompts the
// credential dialog again. The default value is 7 and the valid values are 1 – 1000 AND =<
// RenewalPeriod, otherwise it will result in errors. Value type is an integer.
//
// Default: 7.
func (s *CertificateStore) GetMYWSTEPRenewRetryInterval(ctx context.Context) (int64, error) {
	v, err := s.c.Get(ctx, URIMYWSTEPRenewRetryInterval)
	if err != nil {
		return 0, err
	}
	return v.Int()
}

